using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S0.Computability;

internal sealed class WindowOriginalAcquisitionDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Original-input physical acquisition and simultaneous resources.",
        H("Original-input physical acquisition and simultaneous resources"),
        Blocks(
            Paragraph(Text("For every positive N and every h at least its canonical window count L, only the independently encoded original W at that height and its unit initialize the machine. There is one fixed finite-alphabet eight-track program and two absolute positive constants before all those inputs. No number, height, width or external clock is supplied separately.")),
            Paragraph(Text("One attained run terminates with exact binary registers for both original Horner coordinates, h and N, and with the original composition and matrix column sum. The coordinate growth and strict Fibonacci capacity hold. Every original prefix occurs within that same run with the exact seam, physical counter and Horner column.")),
            Paragraph(Text("The same execution has quadratic local-action time and linear all-prefix persistent charge. The read-only input stays literal at every time; its final head is at the unit position h. The packed tape is retained, all work heads are zero, and unused tracks stay blank. The exact canonical registers have paid copies, trimming, end markers and rewinds.")),
            Paragraph(Text("The zero-window positive case is N=1 with its independent unit. Every extra high null remains an actual input position and a paid counted step. This is acquisition alone: three dependent H calls, including repeated addresses, and six original-height output rows remain separate requirements.")),
            Describe.Lean(DescribeId.Create("original-window-acquisition"), DeclarationHandle.Create("D5/S0/Computability/WindowOriginalAcquisition.original_window_acquisition"), H("original window acquisition"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("With all declared parameters and hypotheses, the exact statement is: original_window_acquisition : Function.Injective (finiteCode (\u03b1 := Symbol)) \u2227 \u2203 A B : \u2115, 0 < A \u2227 0 < B \u2227 \u2200 (h N : \u2115), 1 \u2264 N \u2192 OriginalEncoder.L N \u2264 h \u2192 let w := OriginalEncoder.localWord h N let e := OriginalEncoder.bit N 0 \u2203 T : \u2115, T \u2264 A*(h+1)^2 \u2227 run (initial w e) T = registerEnd w e \u2227 program (registerEnd w e).control = .halt \u2227 RegisterRep (registerEnd w e) 0 (value1 (Original.finalColumns w e)) \u2227 RegisterRep (registerEnd w e) 1 (value2 (Original.finalColumns w e)) \u2227 RegisterRep (registerEnd w e) 2 h \u2227 RegisterRep (registerEnd w e) 3 N \u2227 Original.pair (Original.finalColumns w e) = NativeContinuation.JointLaw.composition (OriginalEncoder.W h N) \u2227 Original.pair (Original.finalColumns w e) = Original.columnSum w \u2227 Original.maximumColumn [] = 0 \u2227 (\u2200 b, Original.maximumColumn (w ++ [b]) \u2264 5*Original.maximumColumn w+2) \u2227 2*Original.maximumColumn w+1 \u2264 5^h \u2227 Original.maximumColumn w \u2264 (5^h-1)/2 \u2227 N < Nat.fib (3*h+3) \u2227 (\u2200 n \u2264 T, charged w e n \u2264 B*(h+1)) \u2227 (\u2200 n \u2264 T, \u2200 t, 0 \u2264 (run (initial w e) n).head t \u2227 (run (initial w e) n).head t \u2264 3*h+6) \u2227 (\u2200 n, (run (initial w e) n).cell sourceTrack=inputSource w e) \u2227 (registerEnd w e).cell workTrack=word (Original.finalColumns w e) \u2227 (\u2200 t : Track,(\u2200 j : Lane,t \u2260 target j) \u2192 t \u2260 sourceTrack \u2192 t \u2260 workTrack \u2192 (registerEnd w e).cell t=fun _=>.blank) \u2227 (\u2200 t : Track,(registerEnd w e).head t=if t=sourceTrack then h else 0) \u2227 (\u2200 j : Lane,(normalized ((Original.finalColumns w e).map (select j))).length \u2264 (Original.finalColumns w e).length+1) \u2227 (\u2200 pre suf : List Window, pre++suf=w \u2192 \u2203 q : \u2115, q \u2264 T \u2227 q \u2264 4+pre.length*(15*h+46) \u2227 run (initial w e) q = base (boundary (inputSource w e) pre.length (columnsAfter [zeros] pre) 0 (.source (seamAfter false pre))) \u2227 Original.pair (columnsAfter [zeros] pre) = NativeContinuation.JointLaw.composition (pre.map Original.letter) \u2227 valueCount (columnsAfter [zeros] pre) = pre.length \u2227 (columnsAfter [zeros] pre).length \u2264 1+3*pre.length)"))), DescribeRole.Theorem)),
        [DocumentEdge.Dependency.Create(GidRef.Create("D5/S0/Computability/WindowOriginalEncoder")), DocumentEdge.Dependency.Create(GidRef.Create("D5/S0/Computability/WindowCanonicalPrefixes"))]));
}
